<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { operations, errorText, money, type OperationsDashboard } from '../../lib/operations';
import { state } from '../../lib/auth';
import AppIcon from '../../ui/AppIcon.vue';
import SchoolCreateDialog from './SchoolCreateDialog.vue';
const router = useRouter();
const data = ref<OperationsDashboard | null>(null);
const loading = ref(false);
const error = ref('');
const creating = ref(false);
const metrics = computed(() => [
  { label: '已开通学校', value: data.value?.summary.schools, unit: '所', hint: `服务中 ${data.value?.summary.activeSchools ?? '—'} 所`, icon: 'school', color: 'blue' },
  { label: '学校管理员', value: data.value?.summary.admins, unit: '人', hint: '已交付的学校管理账号', icon: 'shield', color: 'mint' },
  { label: '学生服务规模', value: data.value?.summary.students, unit: '人', hint: `教师 ${data.value?.summary.teachers ?? '—'} 人 · 课程 ${data.value?.summary.courses ?? '—'} 门`, icon: 'users', color: 'amber' },
  { label: '学校待收费用', value: data.value ? money(data.value.summary.unpaidCents) : undefined, unit: '', hint: '各学校业务账单汇总', icon: 'wallet', color: 'rose' },
]);
const schools = computed(() => [...(data.value?.schools ?? [])].sort((a, b) => b.stats.outstanding - a.stats.outstanding).slice(0, 5));
const noAdmin = computed(() => data.value?.schools.filter(school => school.status === 'active' && school.stats.admins === 0).length ?? 0);
const emptySchools = computed(() => data.value?.schools.filter(school => school.status === 'active' && school.stats.students === 0).length ?? 0);
async function load() { if (loading.value) return; loading.value = true; error.value = ''; try { data.value = await operations.dashboard(); } catch (e) { error.value = errorText(e, '运营工作台暂时无法加载'); } finally { loading.value = false; } }
function created(id: number) { creating.value = false; router.push(`/ops/schools/${id}`); }
onMounted(load);
</script>
<template>
  <div>
    <div class="page-heading"><div><h1 class="page-title">运营工作台</h1><p class="page-description">欢迎回来，{{ state.me?.name }}。一起把每所学校的服务准备好。</p></div><div class="flex gap-2"><button class="btn btn-secondary" :disabled="loading" @click="load"><AppIcon name="refresh" :size="16" />{{ loading ? '更新中' : '刷新' }}</button><button class="btn btn-primary" @click="creating = true"><AppIcon name="plus" :size="17" />开通学校</button></div></div>
    <section class="ops-welcome"><div class="welcome-copy"><div class="eyebrow">学校服务运营</div><h2>让每一所学校，<br class="mobile-break" />都有从容的开始。</h2><p>从开通空间到管理员交付，关注服务状态与规模，让课后服务有序发生。</p><router-link to="/ops/schools" class="welcome-link">查看全部学校<AppIcon name="arrow-right" :size="17" /></router-link></div><div class="welcome-art" aria-hidden="true"><div class="art-orbit" /><span class="art-dot" /><div class="art-school"><AppIcon name="school" :size="72" /><span class="art-check"><AppIcon name="check" :size="18" /></span></div><span class="art-leaf"><AppIcon name="leaf" :size="29" /></span><span class="art-small"><AppIcon name="users" :size="24" /></span></div></section>
    <div v-if="error" class="card p-7" role="alert"><p class="text-[14px] text-danger">{{ error }}</p><button class="btn btn-secondary mt-4" @click="load">重新加载</button></div>
    <template v-else>
      <div class="metrics-grid" :aria-busy="loading"><section v-for="metric in metrics" :key="metric.label" class="metric-card"><div class="flex items-center justify-between gap-2"><span class="text-[12px] font-medium text-ink-2">{{ metric.label }}</span><span class="metric-icon" :class="`icon-tile-${metric.color}`"><AppIcon :name="metric.icon" :size="18" /></span></div><div class="metric-number" :class="{ 'is-money': !metric.unit }">{{ loading ? '—' : metric.value ?? '—' }}<small>{{ metric.unit }}</small></div><p class="mt-2 text-[11px] text-ink-3">{{ metric.hint }}</p></section></div>
      <div class="dashboard-columns"><section class="card min-w-0"><div class="section-heading"><div><h2 class="section-title">学校服务概览</h2><p class="section-subtitle">按待收费用排序 · 展示前 5 所学校</p></div><router-link to="/ops/schools" class="btn btn-ghost btn-sm">全部学校<AppIcon name="chevron-right" :size="15" /></router-link></div><div v-if="loading" class="state-panel" role="status">正在整理学校服务数据…</div><div v-else-if="!schools.length" class="state-panel"><span class="icon-tile icon-tile-blue"><AppIcon name="school" :size="25" /></span><h3>第一所学校，从这里开始</h3><p>开通学校，创建首位管理员，即可开始交付服务。</p><button class="btn btn-primary mt-4" @click="creating = true">开通第一所学校</button></div><div v-else class="school-summaries"><router-link v-for="school in schools" :key="school.id" :to="`/ops/schools/${school.id}`" class="school-summary"><span class="school-initial">{{ school.name.slice(0, 1) }}</span><div class="school-copy"><div class="school-name">{{ school.name }}<span class="badge" :class="school.status === 'active' ? 'badge-green' : 'badge-gray'">{{ school.status === 'active' ? '服务中' : '已停用' }}</span></div><p>{{ school.term }}<span>·</span>{{ school.stats.students }} 名学生<span>·</span>{{ school.stats.courses }} 门课程</p></div><div class="school-money"><strong>{{ money(school.stats.outstanding) }}</strong><small>待收费用</small></div><AppIcon class="summary-arrow" name="chevron-right" :size="16" /></router-link></div><div class="summary-footnote"><AppIcon name="info" :size="14" />待收费用来自学校业务账单，收款由学校线下登记。</div></section>
      <aside class="space-y-5"><section class="card"><div class="section-heading"><div><h2 class="section-title">服务跟进</h2><p class="section-subtitle">把准备工作落到每所学校</p></div><span class="follow-dot" /></div><div class="follow-items"><router-link to="/ops/schools?status=active" class="follow-item"><span class="icon-tile icon-tile-amber"><AppIcon name="users" :size="19" /></span><div><strong>学校资料准备</strong><p>{{ loading ? '正在读取服务情况' : emptySchools ? `${emptySchools} 所服务中学校尚未建立学生档案` : '服务中学校均已有学生档案' }}</p></div><AppIcon name="chevron-right" :size="15" /></router-link><router-link to="/ops/schools?status=active" class="follow-item"><span class="icon-tile icon-tile-mint"><AppIcon name="shield" :size="19" /></span><div><strong>管理员交付</strong><p>{{ loading ? '正在读取账号情况' : noAdmin ? `${noAdmin} 所学校需补充有效管理员` : '每所服务中学校均有管理员' }}</p></div><AppIcon name="chevron-right" :size="15" /></router-link></div></section><section class="delivery-note"><AppIcon name="leaf" :size="25" /><h3>一份清晰的学校交付</h3><ol><li><span>01</span>建立学校空间与当前学期</li><li><span>02</span>交付管理员账号与初始密码</li><li><span>03</span>由学校准备师生、课程与报名</li></ol><button class="btn btn-secondary btn-sm mt-5" @click="creating = true">开通新学校<AppIcon name="arrow-right" :size="15" /></button></section></aside></div>
    </template>
    <SchoolCreateDialog :show="creating" @close="creating = false" @created="created" />
  </div>
</template>
